// src/context/FirebaseContext.tsx
import React, { createContext, useContext, ReactNode } from 'react';
import Firebase from '@/services/firebase/firebaseService';

const FirebaseContext = createContext<Firebase | null>(null);

interface FirebaseProviderProps {
  children: ReactNode;
}

export const FirebaseProvider: React.FC<FirebaseProviderProps> = ({ children }) => {
  // Use useMemo ensures singleton instance is respected across re-renders if needed,
  // though new Firebase() is logically strictly valid too if internal static check works.
  const firebase = new Firebase();
  return (
    <FirebaseContext.Provider value={firebase}>
      {children}
    </FirebaseContext.Provider>
  );
};

export const useFirebase = (): Firebase => {
  const context = useContext(FirebaseContext);
  if (!context) {
    throw new Error("useFirebase must be used within a FirebaseProvider");
  }
  return context;
};
